use std::process;
use test_programs::preview1::open_scratch_directory;

/// Contents that the host places in `test.txt` before running this program.
/// The runtime must not allow the guest to truncate the file, so these bytes
/// must still be intact after the truncation attempt below.
const EXPECTED: &[u8] = b"truncation test file\n";

unsafe fn test_readonly_truncation(dir_fd: wasip1::Fd) {
    const FILENAME: &str = "test.txt";

    // Attempt to open the file with `O_TRUNC`. The preopened directory was
    // mounted with read-only file permissions, so truncation must be rejected
    // by the runtime rather than clobbering the file's contents.
    let result = wasip1::path_open(
        dir_fd,
        0,
        FILENAME,
        wasip1::OFLAGS_TRUNC,
        wasip1::RIGHTS_FD_READ,
        0,
        0,
    );
    assert!(
        result.is_err(),
        "truncating a file in a read-only directory must be rejected"
    );

    // Re-open the file read-only and confirm the runtime left the contents
    // untouched.
    let file_fd = wasip1::path_open(
        dir_fd,
        0,
        FILENAME,
        0,
        wasip1::RIGHTS_FD_READ,
        0,
        0,
    )
    .expect("opening the file for reading");

    let buffer = &mut [0u8; 128];
    let nread = wasip1::fd_read(
        file_fd,
        &[wasip1::Iovec {
            buf: buffer.as_mut_ptr(),
            buf_len: buffer.len(),
        }],
    )
    .expect("reading file content");

    assert_eq!(
        &buffer[..nread],
        EXPECTED,
        "file contents must be unchanged after the rejected truncation"
    );

    wasip1::fd_close(file_fd).expect("closing the file");
}

fn main() {
    // Open the preopened directory mounted with read-only file permissions.
    let dir_fd = match open_scratch_directory("readonly") {
        Ok(dir_fd) => dir_fd,
        Err(err) => {
            eprintln!("{err}");
            process::exit(1)
        }
    };

    unsafe {
        test_readonly_truncation(dir_fd);
    }
}
