use test_programs::wasi::filesystem::types::{DescriptorFlags, ErrorCode, OpenFlags, PathFlags};
use test_programs::wasi::io::streams::StreamError;

/// Contents that the host places in `test.txt` before running this program.
/// The runtime must not allow the guest to truncate the file, so these bytes
/// must still be intact after the truncation attempt below.
const EXPECTED: &[u8] = b"truncation test file\n";

fn main() {
    // Find the preopened directory that was mounted with read-only file
    // permissions.
    let preopens = wasi::filesystem::preopens::get_directories();
    let (dir, _) = preopens
        .iter()
        .find(|(_, name)| name == "readonly")
        .expect("a preopened directory named \"readonly\" must exist");

    let filename = "test.txt";

    // Attempt to open the file with the `TRUNCATE` flag. Because the directory
    // was preopened with read-only file permissions, the runtime must reject
    // this rather than clobbering the file's contents.
    let result = dir.open_at(
        PathFlags::empty(),
        filename,
        OpenFlags::TRUNCATE,
        DescriptorFlags::READ,
    );
    match result {
        Ok(_) => panic!("truncating a file in a read-only directory must be rejected"),
        Err(ErrorCode::NotPermitted | ErrorCode::Access) => {}
        Err(e) => panic!("unexpected error truncating read-only file: {e:?}"),
    }

    // Re-open the file read-only and confirm the runtime left the contents
    // untouched.
    let file = dir
        .open_at(
            PathFlags::empty(),
            filename,
            OpenFlags::empty(),
            DescriptorFlags::READ,
        )
        .expect("opening the file for reading");

    let stream = file.read_via_stream(0).unwrap();
    let mut contents = Vec::new();
    loop {
        match stream.blocking_read(128) {
            Ok(chunk) => contents.extend(chunk),
            Err(StreamError::Closed) => break,
            Err(e) => panic!("failed reading file: {e:?}"),
        }
    }

    assert_eq!(
        contents, EXPECTED,
        "file contents must be unchanged after the rejected truncation"
    );
}
