use std::fs;
use test_programs_artifacts::P1_FILE_TRUNCATION_READONLY;
use wasmtime::{Linker, Module};
use wasmtime_wasi::p1::{WasiP1Ctx, add_to_linker_async};
use wasmtime_wasi::{DirPerms, FilePerms, WasiCtxBuilder};

#[tokio::main(flavor = "multi_thread")]
async fn main() -> wasmtime::Result<()> {
    const ORIGINAL: &[u8] = b"truncation test file\n";

    let dir = tempfile::tempdir()?;
    fs::write(dir.path().join("test.txt"), ORIGINAL)?;

    let engine = wasmtime::Engine::default();
    let mut linker = Linker::<WasiP1Ctx>::new(&engine);
    add_to_linker_async(&mut linker, |t| t)?;

    let mut builder = WasiCtxBuilder::new();
    builder.inherit_stdio();
    // Mount the directory read-only at the file level, but allowing directory
    // mutation, matching the scenario from the task.
    builder.preopened_dir(
        dir.path(),
        "readonly",
        DirPerms::READ | DirPerms::MUTATE,
        FilePerms::READ,
    )?;
    let ctx = builder.build_p1();

    let module = Module::from_file(&engine, P1_FILE_TRUNCATION_READONLY)?;
    let mut store = wasmtime::Store::new(&engine, ctx);
    let instance = linker.instantiate_async(&mut store, &module).await?;
    let start = instance.get_typed_func::<(), ()>(&mut store, "_start")?;
    start.call_async(&mut store, ()).await?;

    let after = fs::read(dir.path().join("test.txt"))?;
    assert_eq!(after, ORIGINAL, "file must be unchanged");
    println!("VERIFIED: guest ran cleanly and file is unchanged ({} bytes)", after.len());
    Ok(())
}
